--[[ SABREUR À TROIS SABRES — animations de la séquence complète (R15)
  1. Dans l'Explorer, sélectionne le Model de ton personnage R15 (avec Humanoid).
  2. Affichage > Barre de commande : colle tout ce script puis Entrée.
  3. Avatar > Éditeur d'animation > choisis le rig > ⋯ > Charger > Sabreur_…
  4. ⋯ > Publier sur Roblox, puis copie l'ID d'animation (rbxassetid://…).
  Marqueurs : Montrer / Cacher (valeur = nom de l'Accessory), Impact, Aura, Explosion.
]]
local rig = game:GetService("Selection"):Get()[1]
assert(rig and rig:FindFirstChildOfClass("Humanoid"), "Sélectionne d'abord ton rig R15 dans l'Explorer.")
local ServerStorage = game:GetService("ServerStorage")
local saves = ServerStorage:FindFirstChild("RBX_ANIMSAVES")
if not saves then saves = Instance.new("Folder") saves.Name = "RBX_ANIMSAVES" saves.Parent = ServerStorage end
local holder = saves:FindFirstChild(rig.Name)
if not holder then holder = Instance.new("ObjectValue") holder.Name = rig.Name holder.Value = rig holder.Parent = saves end
local rad = math.rad
